 function update(dt){worldTime+=dt;if(!running)return;player.inv=Math.max(0,player.inv-dt);player.attack=Math.max(0,player.attack-dt);player.heavy=Math.max(0,player.heavy-dt);player.dodge=Math.max(0,player.dodge-dt);player.comboT-=dt;if(player.comboT<0)player.combo=0;player.parry=Math.max(0,player.parry-dt);let speed=26*dt;if(keys.shift)speed*=1.35;if(keys.a||keys.arrowleft)player.x-=speed;if(keys.d||keys.arrowright)player.x+=speed;if(keys.w||keys.arrowup)player.z-=speed*.75;if(keys.s||keys.arrowdown)player.z+=speed*.75;player.x=clamp(player.x,-40,40);player.z=clamp(player.z,43,96);
 for(let e of enemies){if(e.dead)continue;e.hit=Math.max(0,e.hit-dt);e.stun=Math.max(0,e.stun-dt);if(e.stun>0)continue;let dx=player.x-e.x,dz=player.z-e.z,dist=Math.hypot(dx,dz);if(e.wind>0){e.wind-=dt;if(e.wind<=0&&dist<19&&player.inv<=0){if(player.parry>0){e.stun=.8;damageEnemy(e,15,0);announce('PARADA PERFECTA')}else{player.hp-=e.type==='cirujano'?17:12;player.inv=.48;shake=9;burst(W/2,H*.77,'#ad423a',12)}}}else{if(dist>19){e.x+=Math.sign(dx)*dt*(e.type==='cantor'?7:9);e.z+=Math.sign(dz)*dt*(e.type==='cantor'?6:8)}else{e.attack-=dt;if(e.attack<=0){e.attack=e.type==='cantor'?2.1:1.55;e.wind=.34}}if(e.type==='cantor'&&dist>22&&dist<78){e.attack-=dt;if(e.attack<=0){e.attack=2.4;bolts.push({x:e.x,z:e.z,target:player,speed:22,dmg:12,enemy:true})}}}}
 if(boss){boss.hit=Math.max(0,boss.hit-dt);let dx=player.x-boss.x,dz=player.z-boss.z,dist=Math.hypot(dx,dz);boss.phase=boss.hp<boss.max*.5?2:1;if(dist>25){boss.x+=Math.sign(dx)*dt*4;boss.z+=Math.sign(dz)*dt*3}boss.attack-=dt;if(boss.attack<=0){boss.attack=boss.phase===2?1.35:2;boss.wind=.48;announce(boss.phase===2?'EL CORO SE DESGARRA':'EL CORO INSPIRA')};if(boss.wind>0){boss.wind-=dt;if(boss.wind<=0&&dist<36&&player.inv<=0){if(player.parry>0){damageEnemy(boss,36,0);boss.stun=.5;announce('EL CORO PIERDE UNA NOTA')}else{player.hp-=boss.phase===2?24:18;player.inv=.7;shake=14;flash=.2}}}}
 for(let b of bolts){if(!b.target)continue;let tx=b.target===player?0:b.target.x,tz=b.target===player?player.z:b.target.z,dx=tx-b.x,dz=tz-b.z,d=Math.hypot(dx,dz);if(d<b.speed*dt+2){if(b.target===player){if(player.inv<=0){player.hp-=b.dmg;player.inv=.4;shake=6}}else if(!b.target.dead)damageEnemy(b.target,b.dmg,4);b.dead=true}else{b.x+=dx/d*b.speed*dt;b.z+=dz/d*b.speed*dt}}bolts=bolts.filter(b=>!b.dead);
-particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=200*dt});particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-30*dt);flash=Math.max(0,flash-dt);enemies=enemies.filter(e=>!e.dead||e.hp<=0&&worldTime%1<.9);
+particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=200*dt});particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-30*dt);flash=Math.max(0,flash-dt);enemies=enemies.filter(e=>!e.dead);
 if(player.hp<=0){player.hp=0;running=false;document.getElementById('intro').classList.remove('hidden');document.querySelector('.eyebrow').textContent='LA CIUDAD TE HA RECORDADO';document.querySelector('.card h1').innerHTML='LA VIGILIA<br>NO TERMINA';document.querySelector('.card h2').textContent=`ALMAS RECOGIDAS · ${kills}`;document.querySelector('.card p').textContent='La carne vuelve a la piedra. Pero la campana aún tiene otras voces. Levántate, si recuerdas cómo.';document.getElementById('start').textContent='VOLVER A LEVANTARSE';player.hp=player.max;player.soul=0;enemies=[];boss=null;wave=0;return}
 if(!boss&&enemies.length===0&&between<=0){between=2.5}else if(!boss&&enemies.length===0){between-=dt;if(between<=0){player.hp=Math.min(player.max,player.hp+22);player.soul=Math.min(100,player.soul+14);beginWave()}}
 updateUI()}
 function updateUI(){document.getElementById('hp').style.width=`${100*player.hp/player.max}%`;document.getElementById('soul').style.width=`${player.soul}%`;document.getElementById('soulNum').textContent=Math.floor(player.soul)}
